import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"配置说明","description":"三份 YAML 同目录：config.yaml、admin.yaml、client.yaml。环境变量前缀 KIRIVERS_ / KIRIVERS_ADMIN_ / KIRIVERS_CLIENT_。","frontmatter":{"title":"配置说明","description":"三份 YAML 同目录：config.yaml、admin.yaml、client.yaml。环境变量前缀 KIRIVERS_ / KIRIVERS_ADMIN_ / KIRIVERS_CLIENT_。"},"headers":[],"relativePath":"guide/config/index.md","filePath":"guide/config/index.md","lastUpdated":1790057721000}`),a={name:`guide/config/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to “配置说明”">​</a></h1><p>三份文件必须在<strong>同一文件夹</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config-dir/</span></span>
<span class="line"><span>  config.yaml     # 系统：数据库、存储、缓存、任务、安全</span></span>
<span class="line"><span>  admin.yaml      # 管理平面：addr、TLS、trusted_proxies、static_dir</span></span>
<span class="line"><span>  client.yaml     # 客户端平面：addr、TLS、trusted_proxies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>-config</code> 指向该目录或其中的系统文件。缺文件时加载同目录 <code>*-example.yaml</code>。</p><table tabindex="0"><thead><tr><th>文件</th><th>环境变量前缀</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yaml</code></td><td><code>KIRIVERS_</code></td><td>例：<code>postgres.dsn</code> → <code>KIRIVERS_POSTGRES_DSN</code></td></tr><tr><td><code>admin.yaml</code></td><td><code>KIRIVERS_ADMIN_</code></td><td>例：<code>addr</code> → <code>KIRIVERS_ADMIN_ADDR</code></td></tr><tr><td><code>client.yaml</code></td><td><code>KIRIVERS_CLIENT_</code></td><td>例：<code>addr</code> → <code>KIRIVERS_CLIENT_ADDR</code></td></tr></tbody></table><p><code>trusted_proxies</code> 与 <code>static_dir</code> <strong>不在</strong> <code>config.yaml</code>。它们分别属于平面 YAML。</p><p>任一平面 <code>mode=debug</code> 则整个进程 Gin 为 debug（进程全局）；否则 release。</p><h2 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to “日志”">​</a></h2><p>进程有一路系统日志；管理平面与客户端平面各有 system + access，共五路。每一路：控制台与滚动文件至少启用一个。两边都关则启动失败、不监听。</p><p>环境变量覆盖适合部署注入密钥；日常把三份 YAML 当权威。子页：</p><ul><li><a href="./bootstrap-admin">管理员初始化</a></li><li><a href="./client.yaml">client.yaml</a></li><li><a href="./config.yaml">config.yaml</a></li><li><a href="./cache">缓存</a></li><li><a href="./s3">S3</a></li><li><a href="./local-storage">本机磁盘</a></li><li><a href="./admin.yaml">admin.yaml</a></li><li><a href="./reverse-proxy">反向代理</a></li><li><a href="./cluster">多节点 YAML</a></li><li><a href="./security">安全</a></li></ul>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};